"""Write the exact ten bounded scientific reports and RESULTS.csv from reviewed evidence."""
import csv,json
from pathlib import Path
B=Path(__file__).resolve().parent;ROOT=B.parent
Q=list(csv.DictReader((B/'queue.csv').open(newline='',encoding='utf-8')))
N={x['sample_id']:x for x in csv.DictReader((ROOT/'shared-catalogues'/'TARGET-STATUS.csv').open(newline='',encoding='utf-8'))}
A={x['sample_id']:x for x in json.loads((ROOT/'root-availability.json').read_text(encoding='utf-8'))}
V={
'F011':dict(verdict='REFUTED',period='',epoch='',depth='',finding='The two selected QLP SAP deficits at BTJD 1896.5 and 2628.48 are real blended dips, but historical vet20 S21/S48 difference images and neighbor apertures locate both on TIC 17238865, 60.4 arcsec from the queue target. Its neighbor aperture lost about 10.5% and 9.6%; the target-core change was small. The original cutout was temporary, so this is an inspected prior receipt rather than newly recomputed pixels. The target Gaia period is not established by these dips.',lim='Selected dips are off target; this does not rule out other eclipses of TIC 17238861.',next='Review TIC 17238865 as its own lead if desired; obtain fresh cutouts only if the historical attribution needs remeasurement.'),
'F012':dict(verdict='PLAUSIBLE',period='',epoch='',depth='',finding='S27 has a large complex trough near 2058.07 with adjacent ramps and gaps, plus several other nonuniform troughs. S62 around 3001.87 and S94 around 3874.87 are shallower broad features, also affected by local changes and gaps. These do not supply three measured same-kind centers or a coherent integer-cycle clock. The S27 main deficit persists in KSPSAP, while its 2043.5 trough is suppressed; the same photons are involved.',lim='Eclipse interpretation, event kind, source and cycle count remain insecure. The S3 sector is available but absent from the cached QLP set.',next='Inspect S3 and obtain target-centered pixels at a clean future deep event; compare clock hypotheses only after measured repeat centers.'),
'F013':dict(verdict='PLAUSIBLE',period='',epoch='',depth='',finding='Narrow raw SAP deficits at 1950.849 in S23 and 2685.513 in S50 are each represented by very few cadences and survive KSPSAP at about 5.5 and 2.2 ppt local core depth. Their 734.664-day separation allows many integer aliases; N=27 gives about 27.2098 d, close to but not identical with the Gaia 27.2175-day SB1 period. S23 fresh TESSCut has only three core cadences but places its difference peak near the target; the S50 cutout has no valid core at the narrow event. The broad 1934.5 flag is a trend, not a secure third event.',lim='Two sparse events do not fix a cycle count; S50 source attribution and precise centers remain insecure.',next='Capture another narrow event with high-cadence target and neighbor photometry, then test adjacent integer aliases.'),
'F014':dict(verdict='PROBABLE',period='35.239',epoch='',depth='17',finding='Six clean raw SAP eclipses form two repeating shapes in S41, S55 and S75: one near 2424.617/2812.260/3340.839 and another near 2431.260/2818.863/3347.444. A sparse S15 dip near 1726.468 aligns with the second shape. Each long-baseline spacing is consistent with roughly 35.239 d over 11 and 15 cycles; the two shapes are separated by about 6.60 to 6.64 d, so they are kept as distinct kinds. Bounded integer subharmonic tests find a fully covered S75 P/2-predicted A-kind core at 3358.45 with only 0.76 ppt local loss versus about 24 ppt in the measured eclipses; P/3 and P/4 also have covered extra nulls in S41/S55/S75 (see `lead-alias.json`). KSPSAP reproduces the S41/S55 events. Fresh TESSCut WCS cubes show all six difference peaks on the target across three camera orientations, with difference centroids 0.03 to 0.32 pixel from target WCS. The catalogued VSX EB 38.35 arcsec away has G 16.46 and P 1.1016829 d and cannot simply explain the observed depth or clock. The target Gaia SB2 period is 35.374736 +/- 0.004103 d, about 0.136 d discrepant from this photometric clock.',lim='The target owns the recurring photometric dips, but the Gaia SB2 orbital association and source-specific conjunction geometry are unresolved. Local fit covariances understate long-baseline timing scatter; the approximate period has no defensible formal error yet.',next='Obtain source-specific RV/conjunction timing and independent photometry, then reconcile the 35.239 d eclipse clock with the Gaia 35.3747 d SB2 orbit.'),
'F015':dict(verdict='REFUTED',period='',epoch='',depth='',finding='The retained S94 long-duration windows near 3868 and 3875 have curved baseline ramps and data gaps. S101 around 4108 is a discontinuous level step followed by a slope; S104 around 4197 is a broad trend with no measured flat eclipse core. Broad trapezoid fits hit width bounds, so those fitted centers and depths are not physical timings.',lim='Positive gap/step/ramp evidence refutes the selected eclipse flags; no independent secure repeat was isolated. This does not exclude an unrelated binary signal.',next='Only revisit if independently reduced time series shows a sharp recurring event away from gap boundaries.'),
'F016':dict(verdict='PLAUSIBLE',period='',epoch='',depth='',finding='S85 shows two pronounced raw troughs around 3611.24 and 3624.29, roughly 13.05 d apart, with different local profiles; S23 contains a shallower broad 1943.52 feature. These are not three measured same-kind eclipses or a clock linked to Gaia P 58.9777 d. The exact target has a VSX ACV/rotational classification, which does not by itself refute eclipses. A fresh S85 cutout has strong sky-gradient difference structure and provides no secure source attribution; no positive target-centered difference centroid could be measured.',lim='Eclipse kinds, source and aliases are unresolved; S52 is available but uncached. QLP KSPSAP is absent for S85.',next='Inspect S52 and obtain clean background-subtracted target/neighbor pixel photometry around the two S85 troughs.'),
'F017':dict(verdict='PROBABLE',period='',epoch='',depth='14',finding='Two full raw SAP eclipses at 2835.22350 (S56) and 3561.05438 (S83) have similar roughly 14 ppt profiles. Fresh TESSCut difference cubes locate each on the target, 0.066 and 0.091 pixel from its WCS position; a comparably bright star elsewhere in the cutout does not carry the loss. A third partial ingress occurs at the S83 endpoint around 3584.25 to 3584.35. The two full centers differ by 725.830875 d: N=31 gives 23.413899 d and predicts the partial center 3584.4683, with ingress starting roughly 0.22 d before it. N=25 to 30 put the next same-kind center beyond S83, at least 3585.2487 for N=30, so they cannot explain this observed ingress as the same kind. N=32 to 37 predict well-covered extra S83 cores without similar 14 ppt deficits. This supports N=31 if the partial is same-kind, but an opposite-kind interpretation cannot yet be excluded. Gaia SB1 P 23.411672 d agrees broadly but does not supply the photometric cycle count.',lim='The partial third occasion supports recurrence but its missing center leaves kind and orbital period conditional; no precise period or epoch is adopted. QLP KSPSAP is absent for S56/S83; fresh TESSCut provides a spatial alternative extraction of the same photons, not another observing occasion.',next='Measure a complete next event in an independent pipeline and compare separate eclipse-kind recurrence with source-specific Gaia conjunction timing.'),
'F018':dict(verdict='REFUTED',period='',epoch='',depth='',finding='The early S34/S36 flags are shallow ramp/step valleys and are suppressed in KSPSAP. S64/S87/S90 are broad changes centered near data interruptions. S94 at 3875 is a deep common time that appears across several unrelated queue targets, while S95/S97 flags align with level breaks and monotonic recoveries. Local trapezoids repeatedly hit their width bound instead of measuring stable ingress and egress.',lim='The selected windows have positive trend/gap/step evidence, with no secure same-kind raw eclipses; an unrelated signal remains possible. S89 is available but uncached.',next='Inspect S89 only if a fresh event away from discontinuities establishes an eclipse interpretation.'),
'F019':dict(verdict='REFUTED',period='',epoch='',depth='',finding='The S94 3875 trough rides a large curved decline/recovery and shares its time with unrelated queue targets. S94 3868 and S102 4134/4147 are discontinuous steps across data gaps, not isolated symmetric losses. S104 4197 has a change in slope and baseline. Broad trapezoid fits hit width bounds, so these are not measured eclipse centers.',lim='Positive gap/step/ramp context refutes the selected eclipse flags; this is not a global exclusion of binarity.',next='Require a fresh sharp event with stable baselines before any orbital or source follow-up.'),
'F020':dict(verdict='REFUTED',period='',epoch='',depth='',finding='The S67 selected trough near 3146.56 is a long shallow baseline depression ending at a gap; S94 near 3874.63 is a multi-day curved ramp with a discontinuous recovery at a gap, coincident in time with other queue targets. The broad local fit reaches its width bound, so its apparent 7 ppt depth is not an eclipse measurement.',lim='The two selected windows do not show comparable isolated eclipse profiles or a secure clock. S13 is available but uncached.',next='Review S13 only if an independent sharp event warrants reconsideration of this detector flag.'),
}
fields=['sample_id','tic','sample_stratum','physical_verdict','full_review_completion','novelty_status','period_days','period_error_days','primary_epoch_btjd','depth_ppt','limitations','next_check','report']
rows=[]
for row in Q:
    sid=row['sample_id'];tic=row['tic'];v=V[sid];d=json.loads((B/tic/'lead-measurements.json').read_text(encoding='utf-8'));av=A[sid]
    sec=[c['sector'] for c in d['coverage']];un=av['uncached_sectors'];o=B/tic;report=o/'REPORT.md'
    text=f"# {sid} — TIC {tic}: {v['verdict']}\n\n**Physical finding.** {v['finding']}\n\n**Coverage and evidence.** Verified {len(d['source_receipts'])} source FITS and quality-zero positive SAP in cached sectors {', '.join(map(str,sec))}. The current TESSCut sector service returned {av['status']} and lists uncached sectors {', '.join(map(str,un)) if un else 'none'}. The original bulk flags are screening windows, not fitted centers. Numeric timing/coverage and source SHA-256 receipts: `lead-measurements.json`; same-photon alternative reduction: `lead-alternative.json`; raw and alternative panels are adjacent. "
    if (o/'cutouts'/'pixel-evidence.json').exists():text+='Fresh WCS difference measurements and download hashes: `cutouts/pixel-evidence.json`. '
    if sid=='F017':text+='Independent helper alias audit: `helper-alias.json`; see `../helper-audit.md`. '
    if sid=='F011':text+='Historical off-target receipt: `[local-path-redacted]` and original vet20 report, as checked in `../helper-audit.md`. '
    text+=f"\n\n**Limits.** {v['lim']}\n\n**Next check.** {v['next']}\n\n**Novelty.** {N[sid]['novelty_status']}. This bounded catalogue status is separate from the physical verdict and is not a new-system claim.\n"
    report.write_text(text,encoding='utf-8')
    rows.append(dict(sample_id=sid,tic=tic,sample_stratum=row['sample_stratum'],physical_verdict=v['verdict'],full_review_completion='COMPLETE',novelty_status='SCOPED_NONMATCH',period_days=v['period'],period_error_days='',primary_epoch_btjd=v['epoch'],depth_ppt=v['depth'],limitations=v['lim'],next_check=v['next'],report=str(report.resolve())))
with (B/'RESULTS.csv').open('w',newline='',encoding='utf-8') as f:
    w=csv.DictWriter(f,fieldnames=fields);w.writeheader();w.writerows(rows)
print({v:sum(r['physical_verdict']==v for r in rows) for v in set(r['physical_verdict'] for r in rows)})
